use std::{process::Command,thread,time::Duration,collections::VecDeque};
#[derive(Debug)]struct Disk{filesystem:String,total:u64,available:u64,percent:u32,mount:String}
fn parse(text:&str)->Vec<Disk>{text.lines().skip(1).filter_map(|line|{let v:Vec<_>=line.split_whitespace().collect();if v.len()<6{return None}Some(Disk{filesystem:v[0].into(),total:v[1].parse().ok()?,available:v[3].parse().ok()?,percent:v[4].trim_end_matches('%').parse().ok()?,mount:v[5..].join(" ")})}).collect()}
fn main()->Result<(),Box<dyn std::error::Error>>{if !cfg!(target_os="linux"){return Err("Linux with GNU df is required".into())}let args:Vec<_>=std::env::args().skip(1).collect();let mut watch=false;let mut threshold=90;let mut path="/".to_string();let mut i=0;while i<args.len(){match args[i].as_str(){"--watch"=>watch=true,"--threshold"=>{i+=1;threshold=args.get(i).ok_or("missing threshold")?.parse::<u32>()?;if threshold>100{return Err("threshold is 0..100".into())}},"--path"=>{i+=1;path=args.get(i).ok_or("missing path")?.clone()},"--help"=>{println!("disk-sentinel [--path /] [--threshold 90] [--watch]");return Ok(())},_=>return Err("Unknown option".into())}i+=1;}let mut history=VecDeque::new();loop{let result=Command::new("df").args(["-Pk","--",&path]).env("LC_ALL","C").output()?;if !result.status.success(){return Err(String::from_utf8_lossy(&result.stderr).into_owned().into())}let rows=parse(&String::from_utf8_lossy(&result.stdout));if rows.is_empty(){return Err("No parseable disk row".into())}for d in rows{history.push_back(d.percent);if history.len()>20{history.pop_front();}println!("{} on {}: {}% used, {} / {} KiB available {}",d.filesystem.escape_default(),d.mount.escape_default(),d.percent,d.available,d.total,if d.percent>=threshold{"ALERT"}else{"OK"});println!("Recent usage %: {:?}",history);}if !watch{break}thread::sleep(Duration::from_secs(5));}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn parses_posix_df(){let rows=parse("Filesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda 1000 800 200 80% /\n");assert_eq!(rows.len(),1);assert_eq!((rows[0].available,rows[0].percent),(200,80));assert!(parse("header\ninvalid").is_empty());}}
